-- Promote 깐부 (469), 쓰앵님 (470), 발연기 (471), 띵작 (472), 연기돌 (473), 서브병 (474), 사딸라 (475)
-- from slang_candidates (2026-09-12 morning review, operator approved; draft_payload as-is).
-- All seven checked against the Standard Korean Language Dictionary: no entry. 깐부's etymology
-- is unsettled (several competing theories) and origin says so rather than picking one.
-- 띵작 carries secondary_category 'yaminjeongeum'. 묻고 더블로 가 went to daily expressions instead.
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('469', '깐부', 'Kkan-bu', 'drama', 'daily', '내 편이 되어주는, 믿고 의지하는 진짜 친구', '{"de": "Ein echter Freund, der immer auf deiner Seite steht", "en": "A ride-or-die friend who is always on your team", "es": "Un amigo de verdad que siempre está de tu lado", "ja": "いつも自分の味方でいてくれる本当の友達", "vi": "Người bạn thật sự luôn đứng về phía mình"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Hey, wir sind Kkanbu. Lass uns da nicht aufrechnen.", "es": "Oye, somos kkanbu. No andemos contando estas cosas.", "ja": "おい、俺たちカンブだろ。こんなので計算すんなよ。", "vi": "Này, mình là kkanbu mà. Đừng tính toán mấy chuyện này.", "eng": "Come on, we''re kkanbu. Let''s not keep score over this.", "kor": "야, 우리 깐부잖아. 이런 걸로 계산하지 말자."}, {"de": "Ohne meinen Kkanbu von fünf Jahren hätte ich längst gekündigt.", "es": "Sin mi kkanbu de cinco años ya habría renunciado hace mucho.", "ja": "5年一緒に働いてきたカンブがいなかったら、とっくに辞めてた。", "vi": "Không có kkanbu năm năm chung việc thì tôi nghỉ lâu rồi.", "eng": "Without my kkanbu of five years I''d have quit this job ages ago.", "kor": "5년째 같이 일한 깐부 없으면 나 진작 퇴사했지."}], "definition": "원래 구슬치기·딱지치기에서 한편을 먹은 짝꿍을 가리키던 골목놀이 은어. 지금은 가진 걸 나눠도 아깝지 않은, 믿고 의지하는 진짜 친구라는 뜻으로 넓게 쓴다. 넷플릭스 ''오징어 게임''(2021) 구슬치기 편의 \"우린 깐부잖아\" 대사로 전 세계에 알려졌다.", "definition_i18n": {"de": "Ursprünglich Straßenjargon für den Partner beim Murmelspiel. Heute ein Freund, mit dem man alles teilt — weltweit bekannt durch den Satz \"Wir sind doch Kkanbu\" in Squid Game (2021).", "en": "Originally playground slang for the partner you teamed up with in marbles or ddakji. Now it means a friend so close you would share anything — made globally famous by the line \"We''re kkanbu, aren''t we?\" in Netflix''s Squid Game (2021).", "es": "Originalmente jerga de juegos callejeros para tu compañero de equipo en las canicas. Hoy significa un amigo tan cercano que lo compartirías todo — famoso mundialmente por la frase \"Somos kkanbu, ¿no?\" en El juego del calamar (2021).", "ja": "元はビー玉遊びやめんこで組んだ相棒を指す路地裏の隠語。今は何でも分け合える本当の友達という意味で広く使う。Netflix『イカゲーム』(2021)のビー玉編の「俺たちカンブだろ」というセリフで世界的に知られた。", "vi": "Ban đầu là tiếng lóng trẻ con chỉ người cùng phe khi chơi bắn bi hay đánh quay. Nay có nghĩa là người bạn thân đến mức chia sẻ mọi thứ — nổi tiếng toàn cầu nhờ câu \"Chúng ta là kkanbu mà\" trong Squid Game (2021)."}}]'::jsonb, '어원은 확정되지 않았고 여러 설이 있다 — ①고사성어 ''관포지교(管鮑之交)''의 ''관포''가 아이들 입에서 ''깐보/깐부''로 변했다는 설 ②영어 combo 변형설 ③일본어에서 왔다는 설. 평안도 방언설, 부산·경상도 유래설도 함께 돌아 어느 쪽도 근거가 확실하지 않다. 확실한 것은 1970~80년대 골목놀이에서 쓰이던 은어가 2021년 넷플릭스 ''오징어 게임'' 6화 대사로 전국·해외에 퍼졌다는 점이다.', '{"de": "Die Herkunft ist ungeklärt — Theorien: Verballhornung von 관포지교 (klassische Redewendung über Freundschaft), vom englischen combo oder aus dem Japanischen; auch die regionale Zuordnung ist umstritten. Sicher ist: Der alte Spielplatzjargon wurde durch Folge 6 von Squid Game (2021) weltweit bekannt.", "en": "The etymology is unsettled — theories include a corruption of 관포지교 (a classical idiom about famed friendship), the English word combo, and a Japanese loan; regional claims (Pyongan dialect vs. Busan) also conflict. What is certain is that this old playground slang went nationwide and global through episode 6 of Squid Game (2021).", "es": "La etimología no está resuelta — teorías: deformación de 관포지교 (modismo clásico sobre la amistad), del inglés combo, o préstamo japonés; también se disputa el origen regional. Lo seguro es que esta vieja jerga infantil se hizo global con el episodio 6 de El juego del calamar (2021).", "ja": "語源は未確定で諸説ある — 故事成語「管鮑之交」の変形説、英語comboの変形説、日本語由来説など。平安道方言説と釜山由来説も並立し確証はない。確かなのは、路地裏の隠語が2021年『イカゲーム』第6話で全国・世界に広まったこと。", "vi": "Từ nguyên chưa xác định — các giả thuyết: biến âm của 관포지교 (thành ngữ về tình bạn), từ tiếng Anh combo, hoặc vay mượn tiếng Nhật; nguồn gốc vùng miền cũng chưa thống nhất. Điều chắc chắn là tiếng lóng cũ này lan ra toàn cầu nhờ tập 6 Squid Game (2021)."}'::jsonb, '''우리 깐부잖아''처럼 관계를 확인하거나 부탁을 부드럽게 할 때 쓴다. 친구뿐 아니라 오래 함께한 동료·사업 파트너에게도 쓰며, 기업 제휴 보도자료에도 ''깐부를 맺었다''로 등장할 만큼 대중화됐다. 표준국어대사전에는 없는 말이다.', '{"de": "Oft als \"Wir sind doch Kkanbu, oder?\" verwendet, um Nähe zu bestätigen oder eine Bitte abzumildern. Gilt auch für langjährige Kollegen und Geschäftspartner — sogar Pressemitteilungen sprechen davon, dass zwei Firmen \"Kkanbu wurden\". Nicht im Standardwörterbuch.", "en": "Often used as \"we''re kkanbu, right?\" to confirm closeness or soften a favour. Applies to long-time colleagues and business partners too — even press releases say two companies \"became kkanbu\". Not listed in the Standard Korean Dictionary.", "es": "Se usa como \"somos kkanbu, ¿no?\" para confirmar cercanía o suavizar un favor. También vale para colegas de años y socios; hasta las notas de prensa dicen que dos empresas \"se hicieron kkanbu\". No figura en el diccionario estándar.", "ja": "「俺たちカンブだろ」のように関係を確認したり、お願いを和らげるときに使う。友人だけでなく長年の同僚や事業パートナーにも使い、企業提携の発表で「カンブを結んだ」と書かれるほど一般化した。標準国語大辞典には未収録。", "vi": "Thường nói \"mình là kkanbu mà\" để xác nhận thân thiết hoặc nhờ vả nhẹ nhàng. Dùng cả với đồng nghiệp lâu năm và đối tác; thông cáo báo chí còn viết hai công ty \"kết kkanbu\". Không có trong từ điển chuẩn."}'::jsonb, array['찐친','반모','과몰입'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Ride-or-die buddy / teammate"}, {"lang": "🇯🇵 JA", "text": "相棒、大親友"}, {"lang": "🇨🇳 ZH", "text": "铁哥们、搭档"}, {"lang": "🇻🇳 VI", "text": "Bạn chí cốt, cạ cứng"}, {"lang": "🇪🇸 ES", "text": "Compinche, amigo del alma"}, {"lang": "🇩🇪 DE", "text": "Kumpel fürs Leben"}]'::jsonb),
('470', '쓰앵님', 'Sseu-aeng-nim', 'drama', null, '''선생님''을 애원하듯 늘여 부르는 말', '{"de": "Eine flehende, gedehnte Art, \"Lehrer\" zu sagen", "en": "A pleading, stretched-out way to say \"teacher\"", "es": "Forma alargada y suplicante de decir \"maestro\"", "ja": "「先生」をすがるように伸ばして呼ぶ言い方", "vi": "Cách kéo dài giọng van nài khi gọi \"thầy/cô\""}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Sseu-aeng-nim … könnten Sie nur diese eine Aufgabe ansehen?", "es": "Sseu-aeng-nim… ¿podría revisarme solo esta tarea?", "ja": "スセンニム…今回の課題だけ見てもらえませんか?", "vi": "Sseu-aeng-nim… thầy xem giúp em mỗi bài này thôi được không ạ?", "eng": "Sseu-aeng-nim… could you please just look over this one assignment?", "kor": "쓰앵님… 이번 과제만 좀 봐주시면 안 될까요?"}, {"de": "Der Senior, der mir Excel-Formeln beibrachte, ist mein Lebens-Sseu-aeng-nim.", "es": "El senpai que me enseñó fórmulas de Excel es mi sseu-aeng-nim de la vida.", "ja": "エクセル関数を教えてくれた先輩が人生のスセンニムだ。", "vi": "Anh tiền bối dạy tôi hàm Excel chính là sseu-aeng-nim của đời tôi.", "eng": "The senior who taught me Excel formulas is my life''s sseu-aeng-nim.", "kor": "엑셀 함수 알려준 선배가 내 인생 쓰앵님이다."}], "definition": "''선생님''을 절박하게 애원하는 말투로 늘여 발음한 말. JTBC 드라마 ''SKY 캐슬''(2018~2019)에서 한서진(염정아)이 입시 코디네이터에게 매달리며 부른 발음이 그대로 유행어가 됐다. 지금은 실제 선생님뿐 아니라 무언가를 대신 해결해 줄 고수·전문가를 우러러 부를 때도 쓴다.", "definition_i18n": {"de": "\"Lehrer\" zu einem verzweifelten Flehen gedehnt. Stammt aus SKY Castle (2018–19), wo Han Seo-jin die Aufnahme-Beraterin so anfleht. Heute auch scherzhaft für jeden Experten, den man um Hilfe bittet.", "en": "\"Teacher\" (선생님) stretched into a desperate plea. It comes from JTBC''s SKY Castle (2018–19), where Han Seo-jin begs her daughter''s admissions coach this way. Today it is also used half-jokingly for any expert you are begging for help.", "es": "\"Maestro\" alargado en una súplica desesperada. Viene de SKY Castle (2018-19), donde Han Seo-jin le ruega así a la coordinadora de admisiones. Hoy se usa también en broma para cualquier experto al que le pides ayuda.", "ja": "「先生님」を必死にすがるように伸ばした発音。JTBCドラマ『SKYキャッスル』(2018~19)で韓緖珍が入試コーディネーターにすがる場面の発音がそのまま流行語になった。今は実際の教師だけでなく、頼りたい達人・専門家を仰ぐときにも使う。", "vi": "\"Thầy/cô\" bị kéo dài thành lời van nài. Xuất phát từ phim SKY Castle (2018–19), khi Han Seo-jin nài nỉ người cố vấn tuyển sinh. Nay còn dùng nửa đùa cho bất kỳ cao thủ nào mình đang nhờ vả."}}]'::jsonb, 'JTBC 드라마 ''SKY 캐슬''(2018-11~2019-02) 속 한서진(염정아)의 대사 발음에서 나왔다. 배우 본인은 라디오에서 ''선생님으로 발음했는데 신조어가 된 줄 몰랐다''는 취지로 밝혀, 의도적으로 만든 유행어가 아니라 연기 중 나온 발음이 시청자에게 포착돼 퍼진 경우다. ''SKY 캐슬''은 이 밖에도 ''전적으로 저를 믿으셔야 합니다'' 등 여러 유행어를 남겼다.', '{"de": "Aus Han Seo-jins Sprechweise in SKY Castle (Nov. 2018–Feb. 2019). Die Schauspielerin sagte im Radio, sie habe einfach 선생님 ausgesprochen und nicht gewusst, dass daraus ein Modewort wurde — ein zufälliger, vom Publikum aufgegriffener Spruch.", "en": "From Han Seo-jin''s line delivery in JTBC''s SKY Castle (Nov 2018–Feb 2019). The actress later said on radio that she was simply pronouncing 선생님 and did not realise it had become a buzzword — so this is an accidental catchphrase caught by viewers, not a scripted one.", "es": "De la entonación de Han Seo-jin en SKY Castle (nov 2018–feb 2019). La actriz contó en radio que solo pronunciaba 선생님 y no sabía que se había vuelto una palabra de moda: un latiguillo accidental captado por el público.", "ja": "JTBCドラマ『SKYキャッスル』(2018.11~2019.2)の韓緖珍のセリフの発音から。女優本人はラジオで「先生님と発音していただけで新造語になったとは知らなかった」と語っており、意図せぬ発音が視聴者に拾われて広まった例。", "vi": "Từ cách thoại của Han Seo-jin trong SKY Castle (11/2018–2/2019). Nữ diễn viên kể trên radio rằng cô chỉ phát âm 선생님 và không biết nó thành từ thời thượng — một câu cửa miệng vô tình được khán giả bắt lấy."}'::jsonb, '애원·아부하는 말투가 핵심이라 진지한 호칭으로는 쓰지 않는다. 실제 교실에서 선생님께 이렇게 부르면 장난으로 받아들여지니 주의. 드라마를 아는 또래끼리, 또는 고수에게 농담 섞어 부탁할 때 어울린다.', '{"de": "Entscheidend ist der flehende, schmeichelnde Ton — nie als ernste Anrede. Eine echte Lehrkraft so zu nennen wirkt wie ein Scherz. Passt unter Gleichaltrigen, die die Serie kennen, oder als halb scherzhafte Bitte an Könner.", "en": "The whole point is the pleading, sucking-up tone, so never use it as a serious form of address. Calling a real teacher this in class reads as a joke. It fits peers who know the drama, or a half-joking plea to someone skilled.", "es": "Lo esencial es el tono suplicante y adulador, así que nunca como tratamiento serio. Llamar así a un profesor real suena a broma. Encaja entre pares que conocen la serie o al pedir algo medio en broma a alguien hábil.", "ja": "すがる・媚びる口調が肝なので真面目な呼称としては使わない。実際の授業で先生をこう呼ぶと冗談扱いされるので注意。ドラマを知る同世代同士や、達人への冗談交じりのお願いに合う。", "vi": "Điểm mấu chốt là giọng van nài, nịnh nọt, nên đừng dùng như cách xưng hô nghiêm túc. Gọi thầy cô thật như vậy sẽ bị coi là đùa. Hợp khi nói với bạn bè biết phim, hoặc nhờ vả nửa đùa người giỏi."}'::jsonb, array['과몰입','인생드라마','엄근진'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "\"Teeeacher\" (pleading)"}, {"lang": "🇯🇵 JA", "text": "スセンニム(すがる「先生」)"}, {"lang": "🇨🇳 ZH", "text": "老~师(哀求语气)"}, {"lang": "🇻🇳 VI", "text": "Thầyyy ơi (giọng nài nỉ)"}, {"lang": "🇪🇸 ES", "text": "Maeeestro (suplicando)"}, {"lang": "🇩🇪 DE", "text": "Leeehrer (flehend)"}]'::jsonb),
('471', '발연기', 'Bal-yeon-gi', 'drama', null, '보기 민망할 만큼 형편없는 연기', '{"de": "Schauspiel, das so schlecht ist, dass es wehtut", "en": "Acting bad enough to make you cringe", "es": "Actuación tan mala que da vergüenza ajena", "ja": "見ていて恥ずかしくなるほど下手な演技", "vi": "Diễn xuất tệ đến mức ngượng thay"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Das Drehbuch ist gut, aber das miese Spiel der Hauptrolle macht es unschaubar.", "es": "El guion es bueno, pero la actuación pésima del protagonista no hay quien la vea.", "ja": "脚本はいいのに主演の棒演技で見てられない。", "vi": "Kịch bản hay mà diễn xuất tệ của vai chính làm không xem nổi.", "eng": "The script is good but the lead''s terrible acting makes it unwatchable.", "kor": "대본은 좋은데 주연 발연기 때문에 못 보겠어."}, {"de": "In Folge 1 war das Spiel hölzern, aber bis Folge 8 wurde es deutlich besser.", "es": "En el episodio 1 actuaba fatal, pero para el 8 había mejorado un montón.", "ja": "1話は棒演技だったのに8話あたりで一気に良くなってた。", "vi": "Tập 1 diễn đơ lắm mà đến tập 8 tiến bộ hẳn.", "eng": "Episode 1 was rough acting, but by episode 8 they''d improved a lot.", "kor": "1화는 발연기였는데 8화쯤 되니까 확 늘었더라."}], "definition": "''발''과 ''연기''를 붙인 말로, 발로 한 것 같은 형편없는 연기를 뜻한다. 대사를 국어책 읽듯 읽거나 감정·시선 처리가 어색한 연기가 대표적이다. 한국어에서 ''발-''은 ''발번역'', ''발퀄''처럼 무엇이든 질이 낮다는 뜻을 더하는 접두사로 쓰인다.", "definition_i18n": {"de": "''발'' (Fuß) + ''연기'' (Schauspiel): so gespielt, als hätte man die Füße benutzt — monotones Ablesen, hölzerne Emotionen. Im Slang ist ''발-'' ein Präfix für Pfusch, etwa 발번역 (miese Übersetzung).", "en": "''발'' (foot) + ''연기'' (acting): acting so poor it looks done with the feet — flat line-reading, awkward emotion, unfocused eyes. In Korean slang ''발-'' is a productive prefix meaning shoddy, as in 발번역 (terrible translation).", "es": "''발'' (pie) + ''연기'' (actuación): actuar como si lo hicieras con los pies — leer el guion sin alma, emociones torpes. En argot coreano ''발-'' es un prefijo que significa chapucero, como en 발번역 (traducción penosa).", "ja": "「足」+「演技」で、足でやったような下手な演技。教科書を読むような棒読みや、感情・目線が不自然な演技を指す。韓国語の「발-」は「발번역(ひどい翻訳)」のように質の低さを表す接頭辞。", "vi": "''발'' (chân) + ''연기'' (diễn xuất): diễn như làm bằng chân — đọc thoại như đọc sách, cảm xúc gượng gạo. Trong tiếng lóng Hàn, ''발-'' là tiền tố chỉ chất lượng kém, như 발번역 (dịch dở tệ)."}}]'::jsonb, '2000년대에 등장한 인터넷 신조어로, 사용례는 2000년대 중반부터 본격적으로 발굴된다. 케이블·인터넷 다시보기가 퍼지면서 시청자가 같은 장면을 반복해 보고 연기력을 품평하게 된 환경이 배경으로 지목되지만, 최초 사용자나 정확한 등장 시점을 특정한 기록은 없다.', '{"de": "Eine Internet-Prägung der 2000er, belegt vor allem ab Mitte des Jahrzehnts. Meist mit der Verbreitung von Kabel- und Online-Wiederholungen erklärt, die mehrfaches Ansehen und Kritik ermöglichten — eine Erstverwendung ist nicht dokumentiert.", "en": "An internet coinage from the 2000s, with documented usage taking off in the mid-2000s. It is usually tied to the spread of cable and online replays, which let viewers rewatch and critique performances — but no source pins down a first user or exact date.", "es": "Acuñación de internet de los 2000, con uso documentado desde mediados de esa década. Se suele atribuir a la difusión del cable y las repeticiones en línea, que permitieron revisar y criticar actuaciones; ninguna fuente fija un primer uso.", "ja": "2000年代に生まれたネット新語で、使用例は2000年代半ばから本格的に見つかる。ケーブルやネット再視聴の普及で同じ場面を繰り返し見て演技を評する環境が背景とされるが、初出や初使用者を特定した記録はない。", "vi": "Từ mới trên mạng xuất hiện những năm 2000, dùng nhiều từ giữa thập niên. Thường được gắn với việc truyền hình cáp và xem lại trực tuyến giúp khán giả xem đi xem lại và bình phẩm diễn xuất; không nguồn nào xác định lần dùng đầu tiên."}'::jsonb, '배우 개인을 공격하는 말이라 당사자 앞이나 공개 댓글에서는 조심해야 한다. 반대말로는 ''인생 연기''가 있고, 아이돌 출신 배우에게 붙던 꼬리표라 ''연기돌''과 함께 자주 등장한다.', '{"de": "Der Ausdruck greift eine konkrete Person an — vor ihr oder in öffentlichen Kommentaren also vorsichtig verwenden. Gegenteil ist 인생 연기; taucht oft zusammen mit 연기돌 (Idol-Schauspieler) auf.", "en": "It attacks a specific performer, so be careful using it to their face or in public comments. Its opposite is 인생 연기 (career-best acting), and it often appears alongside 연기돌 (idol-turned-actor), a label it long shadowed.", "es": "Ataca a un intérprete concreto, así que cuidado al usarlo delante de esa persona o en comentarios públicos. Su opuesto es 인생 연기 (la mejor actuación de su carrera); suele salir junto a 연기돌 (ídolo actor).", "ja": "特定の俳優個人を叩く言葉なので、本人の前や公開コメントでは注意。反対語は「인생 연기(人生演技)」。アイドル出身俳優に付きまとったレッテルで「연기돌」とセットで出やすい。", "vi": "Đây là lời công kích cá nhân diễn viên, nên cẩn thận khi nói trước mặt họ hay bình luận công khai. Từ trái nghĩa là 인생 연기; hay đi kèm 연기돌 (idol chuyển sang đóng phim)."}'::jsonb, array['인생 연기','연기돌','캐붕'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Wooden / cringe acting"}, {"lang": "🇯🇵 JA", "text": "棒演技、大根役者"}, {"lang": "🇨🇳 ZH", "text": "演技尬、面瘫演技"}, {"lang": "🇻🇳 VI", "text": "Diễn đơ, diễn tệ"}, {"lang": "🇪🇸 ES", "text": "Actuación de madera"}, {"lang": "🇩🇪 DE", "text": "Hölzernes Schauspiel"}]'::jsonb),
('472', '띵작', 'Tting-jak', 'drama', 'yaminjeongeum', '''명작''을 글자 모양대로 비튼 말 — 진짜 잘 만든 작품', '{"de": "Formverdrehte Schreibung von 명작 — ein echtes Meisterwerk", "en": "A shape-based respelling of 명작 — a genuine masterpiece", "es": "Reescritura visual de 명작 — una auténtica obra maestra", "ja": "「명작(名作)」を字形で崩した語 — 本当の傑作", "vi": "Cách viết biến hình của 명작 — một kiệt tác thật sự"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Das ist echt ein Meisterwerk — vertrau mir und schau nur Folge 1.", "es": "Esta es una obra maestra de verdad, confía y mírate el episodio 1.", "ja": "これマジで神作だから騙されたと思って1話だけ見て。", "vi": "Phim này kiệt tác thật đấy, cứ tin tôi xem thử tập 1 đi.", "eng": "This one''s a genuine masterpiece — just trust me and watch episode 1.", "kor": "이거 진짜 띵작이니까 속는 셈 치고 1화만 봐."}, {"de": "Eine zehn Jahre alte Serie — und immer noch ein Meisterwerk.", "es": "Es una serie de hace diez años y sigue siendo una obra maestra.", "ja": "10年前のドラマなのに今見ても神作だ。", "vi": "Phim mười năm trước mà giờ xem vẫn là kiệt tác.", "eng": "It''s a ten-year-old drama and it still holds up as a masterpiece.", "kor": "10년 전 드라마인데 지금 봐도 띵작이다."}], "definition": "''명작(名作)''의 ''명''을 모양이 닮은 ''띵''으로 바꿔 쓴 말. 뜻은 명작과 같지만 진지함을 덜어낸 장난스러운 칭찬이라, 예술적 걸작보다는 ''이건 진짜 물건이다'' 싶은 드라마·영화·밈에 즐겨 붙인다. 노래에 쓰면 ''띵곡''이 된다.", "definition_i18n": {"de": "명작 (Meisterwerk) mit 명 ersetzt durch das ähnlich aussehende 띵. Gleiche Bedeutung, aber ohne Ernst — verspieltes Lob, eher für eine großartige Serie, einen Film oder ein Meme als für Hochkultur. Für Songs sagt man 띵곡.", "en": "명작 (masterpiece) with 명 swapped for the visually similar 띵. Same meaning, but with the seriousness drained out — it is playful praise, used less for high art than for a drama, film or meme that is simply superb. The song equivalent is 띵곡.", "es": "명작 (obra maestra) con 명 cambiado por el visualmente parecido 띵. Mismo significado pero sin solemnidad: elogio juguetón, más para una serie, peli o meme buenísimos que para alta cultura. Para canciones existe 띵곡.", "ja": "「명작(名作)」の「명」を字形が似た「띵」に替えた語。意味は名作と同じだが真面目さを抜いたふざけた褒め言葉で、芸術的傑作より「これは本物だ」と思うドラマ・映画・ミームに使う。曲なら「띵곡」。", "vi": "명작 (kiệt tác) đổi 명 thành 띵 nhìn na ná. Nghĩa như cũ nhưng bớt nghiêm túc — lời khen tếu, hay dùng cho phim, meme xuất sắc hơn là nghệ thuật cao siêu. Với bài hát thì là 띵곡."}}]'::jsonb, '야민정음에서 나왔다. 야민정음은 한글 자모를 모양이 닮은 다른 글자로 바꿔 쓰는 인터넷 표기 놀이로, ''멍멍이→댕댕이'', ''귀엽다→커엽다''가 같은 원리다. ''명''의 ㅁ+ㅕ가 붙어 보이는 형태를 ''ㄸ''으로 읽어 ''띵''이 됐다. 2010년대 후반 커뮤니티에서 퍼져 2020년 무렵 방송·기사에서도 다뤄질 만큼 알려졌다.', '{"de": "Aus dem Yaminjeongeum, dem Internetspiel, Hangul durch ähnlich aussehende Zeichen zu ersetzen (멍멍이→댕댕이). Das ㅁ+ㅕ in 명 liest sich als ㄸ, daher 띵. Verbreitete sich Ende der 2010er in Foren und war um 2020 auch in den Medien Thema.", "en": "From yaminjeongeum, the internet game of respelling Hangul with visually similar letters (멍멍이→댕댕이, 귀엽다→커엽다). The ㅁ+ㅕ cluster in 명 reads as ㄸ, giving 띵. It spread through online communities in the late 2010s and was covered in the press by around 2020.", "es": "Del yaminjeongeum, el juego de reescribir hangul con letras de forma parecida (멍멍이→댕댕이). El grupo ㅁ+ㅕ de 명 se lee como ㄸ, de ahí 띵. Se difundió en foros a finales de los 2010 y llegó a la prensa hacia 2020.", "ja": "ヤミン正音(ハングルを字形の似た文字に置き換えるネット遊び)由来。「멍멍이→댕댕이」「귀엽다→커엽다」と同じ原理で、「명」のㅁ+ㅕがㄸに見えることから「띵」に。2010年代後半にコミュニティで広がり、2020年頃には報道でも扱われた。", "vi": "Từ yaminjeongeum — trò viết lại Hangul bằng chữ trông giống (멍멍이→댕댕이). Cụm ㅁ+ㅕ trong 명 nhìn như ㄸ nên thành 띵. Lan trên cộng đồng mạng cuối thập niên 2010, đến khoảng 2020 thì lên cả báo chí."}'::jsonb, '칭찬이지만 장난기가 섞인 표기라 보고서·리뷰 기사 같은 격식 있는 글에는 쓰지 않는다. 같은 원리로 만든 ''띵곡''(명곡)과 짝으로 알아두면 좋다. 어느 쪽으로 검색해도 뜻은 ''명작''이며 표준국어대사전에는 없다.', '{"de": "Ein Lob, aber die verspielte Schreibung gehört nicht in formelle Texte. Am besten zusammen mit 띵곡 (aus 명곡) lernen. Bedeutet schlicht 명작 und steht nicht im Standardwörterbuch.", "en": "It is praise, but the playful spelling keeps it out of formal writing like reports or published reviews. Learn it alongside 띵곡 (from 명곡, a great song), built the same way. It simply means 명작 and is not in the Standard Korean Dictionary.", "es": "Es elogio, pero por lo juguetón de la grafía no se usa en textos formales. Conviene aprenderlo junto a 띵곡 (de 명곡), formado igual. Significa simplemente 명작 y no está en el diccionario estándar.", "ja": "褒め言葉だが遊びの表記なので、報告書や記事など硬い文章では使わない。同じ原理の「띵곡(名曲)」とセットで覚えるとよい。意味は「명작」そのもので標準国語大辞典には未収録。", "vi": "Là lời khen nhưng cách viết tếu nên không dùng trong văn bản trang trọng. Nên học cùng 띵곡 (từ 명곡) vì cùng nguyên tắc. Nghĩa chính là 명작, không có trong từ điển chuẩn."}'::jsonb, array['띵곡','레전드','인생드라마'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Masterpiece (playful spelling)"}, {"lang": "🇯🇵 JA", "text": "神作(名作の崩し字)"}, {"lang": "🇨🇳 ZH", "text": "神作(名作的谐形写法)"}, {"lang": "🇻🇳 VI", "text": "Kiệt tác (viết biến hình)"}, {"lang": "🇪🇸 ES", "text": "Obra maestra (grafía lúdica)"}, {"lang": "🇩🇪 DE", "text": "Meisterwerk (Spielschreibung)"}]'::jsonb),
('473', '연기돌', 'Yeon-gi-dol', 'drama', 'kpop', '아이돌이면서 배우로도 활동하는 사람', '{"de": "Ein Idol, das auch als Schauspieler arbeitet", "en": "An idol who also acts in dramas and films", "es": "Un ídolo que también actúa en series y cine", "ja": "アイドルでありながら俳優としても活動する人", "vi": "Idol đồng thời đóng phim"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Die Idol-Schauspieler von heute können wirklich spielen.", "es": "Los ídolos-actores de ahora actúan de verdad bien.", "ja": "最近の演技ドル、本当に演技うまいよね。", "vi": "Dạo này mấy idol đóng phim diễn hay thật.", "eng": "Idol-actors these days are genuinely good at acting.", "kor": "요즘 연기돌들 연기 진짜 잘하더라."}, {"de": "Fing als Idol-Schauspieler an und ist jetzt als richtiger Schauspieler etabliert.", "es": "Empezó como ídolo-actor y ahora está consolidado como actor.", "ja": "演技ドルとして始めたけど、今は完全に俳優として定着した。", "vi": "Bắt đầu từ idol đóng phim mà giờ đã thành diễn viên thực thụ.", "eng": "They started out as an idol-actor and are now established as a proper actor.", "kor": "연기돌로 시작했는데 지금은 완전 배우로 자리 잡았어."}], "definition": "''연기''와 ''아이돌''을 합친 말로, 아이돌 그룹 활동을 하면서 드라마·영화 연기도 병행하는 사람을 가리킨다. 아이돌에서 정식 배우로 넘어가는 중간 단계로도 본다. 음악·예능만으로는 대중 인지도를 넓히기 어렵고 활동 수명도 짧기 때문에 택하는 생존 전략이라는 분석이 흔하다.", "definition_i18n": {"de": "''연기'' (Schauspiel) + ''아이돌'': jemand, der in einer Idol-Gruppe aktiv ist und zugleich Rollen spielt — oft als Zwischenschritt zum vollen Schauspielberuf gesehen. Meist als Überlebensstrategie gedeutet, da Musik und Shows nur ein begrenztes Publikum erreichen und Idol-Karrieren kurz sind.", "en": "''연기'' (acting) + ''아이돌'' (idol): someone active in an idol group who also takes drama and film roles, often seen as a halfway step toward becoming a full actor. Commentary usually frames it as a survival strategy, since music and variety alone reach a limited audience and idol careers are short.", "es": "''연기'' (actuación) + ''아이돌'': alguien activo en un grupo ídolo que además actúa, visto como paso intermedio hacia ser actor pleno. Suele analizarse como estrategia de supervivencia, ya que la música y los programas llegan a un público limitado y la carrera ídolo es corta.", "ja": "「演技」+「アイドル」。アイドル活動をしながらドラマ・映画にも出る人。アイドルから本格俳優への中間段階とも見られる。音楽やバラエティだけでは一般層への認知が広がらず活動寿命も短いため選ぶ生存戦略と分析されることが多い。", "vi": "''연기'' (diễn xuất) + ''아이돌'': người vừa hoạt động nhóm idol vừa đóng phim, được xem là bước trung gian để thành diễn viên thực thụ. Thường được phân tích như chiến lược sinh tồn vì âm nhạc và gameshow chỉ tiếp cận lượng khán giả hạn chế và đời idol thì ngắn."}}]'::jsonb, '''-돌''은 ''아이돌''의 뒷글자를 떼어 만든 접미사로, ''예능돌'', ''요리돌''처럼 아이돌이 겸하는 분야를 앞에 붙여 새 말을 만드는 데 널리 쓰인다. ''연기돌''은 그중 가장 자리를 잡은 말이다. 초기에는 ''아이돌 출신''이라는 수식 자체가 연기력 논란과 붙어 다녔지만, 2020년대 들어 연기력을 인정받는 사례가 늘며 언론도 ''꼬리표를 뗀 연기돌''이라는 식으로 다루고 있다.', '{"de": "''-돌'' ist ein aus 아이돌 gekürztes Suffix, das an das Feld gehängt wird, in dem ein Idol nebenbei arbeitet (예능돌, 요리돌); 연기돌 ist das etablierteste. Früher stand ''Ex-Idol'' für schwaches Schauspiel, doch in den 2020ern ernteten genug Anerkennung, sodass die Presse von Idol-Schauspielern schreibt, die ''das Etikett abgelegt'' haben.", "en": "''-돌'' is a suffix clipped from 아이돌 and attached to whatever field an idol moonlights in (예능돌, 요리돌); 연기돌 is the most established of them. Early on, being ''ex-idol'' was shorthand for weak acting, but through the 2020s enough idols earned acclaim that the press now writes about idol-actors ''shedding the label''.", "es": "''-돌'' es un sufijo recortado de 아이돌 que se une al campo en que el ídolo incursiona (예능돌, 요리돌); 연기돌 es el más asentado. Al principio ''ex ídolo'' equivalía a mala actuación, pero en los 2020 muchos se ganaron elogios y la prensa habla de ídolos-actores que ''se quitaron la etiqueta''.", "ja": "「-돌」は「아이돌」から取った接尾辞で、アイドルが兼ねる分野を前に付けて新語を作る(예능돌、요리돌など)。中でも「연기돌」が最も定着した。初期は「アイドル出身」自体が演技力論争と結び付いたが、2020年代に入り実力を認められる例が増え、報道も「レッテルを外した演技ドル」と扱う。", "vi": "''-돌'' là hậu tố cắt từ 아이돌, ghép với lĩnh vực idol lấn sân (예능돌, 요리돌); 연기돌 là từ định hình nhất. Ban đầu ''xuất thân idol'' đồng nghĩa với diễn dở, nhưng sang thập niên 2020 nhiều người được công nhận nên báo chí viết về idol diễn viên ''gỡ được cái mác''."}'::jsonb, '중립적인 분류어지만 문맥에 따라 ''아직 진짜 배우는 아니다''라는 뉘앙스가 묻어날 수 있어, 연기로 인정받은 사람에게는 그냥 ''배우''라고 부르는 편이 안전하다. ''발연기''와 함께 쓰이면 비판적 맥락이 된다.', '{"de": "Grundsätzlich neutral, kann je nach Kontext aber ''noch kein echter Schauspieler'' mitschwingen — bei anerkannten Darstellern ist schlicht 배우 (Schauspieler) sicherer. Zusammen mit 발연기 wird der Ton kritisch.", "en": "Broadly neutral, but depending on context it can imply ''not a real actor yet'' — so for someone acclaimed for their acting, plain ''배우'' (actor) is the safer word. Paired with 발연기 it turns critical.", "es": "Es neutro en general, pero según el contexto puede sugerir ''aún no es actor de verdad''; para alguien reconocido por su actuación, mejor decir simplemente 배우 (actor). Junto a 발연기 el tono se vuelve crítico.", "ja": "基本は中立的な分類語だが、文脈によっては「まだ本物の俳優ではない」という含みが出るため、演技で認められた人には単に「배우(俳優)」と呼ぶ方が安全。「발연기」と並ぶと批判的な文脈になる。", "vi": "Về cơ bản trung tính, nhưng tuỳ ngữ cảnh có thể hàm ý ''chưa phải diễn viên thật sự'' — với người đã được công nhận thì gọi 배우 (diễn viên) là an toàn hơn. Đi kèm 발연기 thì mang sắc thái chê."}'::jsonb, array['발연기','덕질','최애','인생캐'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Idol-actor"}, {"lang": "🇯🇵 JA", "text": "演技ドル"}, {"lang": "🇨🇳 ZH", "text": "演技爱豆、演员爱豆"}, {"lang": "🇻🇳 VI", "text": "Idol diễn viên"}, {"lang": "🇪🇸 ES", "text": "Ídolo-actor"}, {"lang": "🇩🇪 DE", "text": "Idol-Schauspieler"}]'::jsonb),
('474', '서브병', 'Seo-beu-byeong', 'drama', 'love', '주인공보다 서브 남주·여주에게 더 빠지는 증상', '{"de": "Sich mehr in die Nebenfigur als in die Hauptfigur verlieben", "en": "Falling harder for the second lead than the main one", "es": "Enamorarse más del segundo protagonista que del principal", "ja": "主人公よりサブ主人公にハマってしまう症状", "vi": "Chứng mê nam/nữ phụ hơn cả vai chính"}'::jsonb, null, '[{"type": "명사", "examples": [{"de": "Schon wieder Second-Lead-Syndrom — ich mag den Zweiten lieber.", "es": "Otra vez con el síndrome del segundo protagonista; me gusta más el secundario.", "ja": "また第二男子病にかかった。今回もサブの方が好き。", "vi": "Tôi lại mắc bệnh nam phụ rồi. Lần này cũng thích vai phụ hơn.", "eng": "I''ve got second-lead syndrome again — I like the second guy more, as usual.", "kor": "나 또 서브병 걸렸어. 이번에도 서브가 더 좋아."}, {"de": "Ich konzentriere mich nur auf den Hauptdarsteller, um kein Second-Lead-Syndrom zu bekommen.", "es": "Me obligo a fijarme solo en el protagonista para no pillar el síndrome.", "ja": "サブ病にかかりたくないから主人公だけ見てる。", "vi": "Tôi cố chỉ tập trung vào nam chính để khỏi mắc bệnh nam phụ.", "eng": "I''m forcing myself to focus on the male lead so I don''t catch second-lead syndrome.", "kor": "서브병 걸리기 싫어서 남주한테만 집중하는 중."}], "definition": "''서브(sub)''에 ''병(病)''을 붙인 말로, 드라마나 웹툰에서 주인공 상대역보다 이뤄질 가능성이 없는 서브 남주(또는 서브 여주)에게 더 마음이 쏠리는 상태를 병에 비유한 것. 서브가 더 다정하거나 매력적인데 결말이 정해져 있어 애잔함과 답답함을 동시에 느끼게 되는 게 핵심이다. 실제 질병이 아니라 팬들이 자기 감정을 농담조로 부르는 말이다.", "definition_i18n": {"de": "''sub'' + ''병'' (Krankheit): der Zustand, für die zweite Haupt­figur zu schwärmen, die keine echte Chance hat. Der Reiz: Sie ist oft netter oder attraktiver, während das Ende feststeht — man fühlt Zärtlichkeit und Frust zugleich. Eine scherzhafte Selbstdiagnose, keine echte Krankheit.", "en": "''sub'' + ''병'' (illness): the state of rooting for the second male (or female) lead, who has no real chance with the protagonist. The point is that the second lead is often kinder or more appealing while the ending is already fixed — so you feel tender and frustrated at once. It is a joking self-diagnosis, not a real condition.", "es": "''sub'' + ''병'' (enfermedad): el estado de preferir al segundo protagonista, que no tiene ninguna opción real. La clave es que suele ser más tierno o atractivo mientras el final ya está decidido, así que sientes ternura y frustración a la vez. Es un autodiagnóstico en broma, no una dolencia.", "ja": "「サブ」+「病」。ドラマやウェブトゥーンで、結ばれる見込みのないサブ主人公の方に心が傾いてしまう状態を病に例えた語。サブの方が優しく魅力的なのに結末は決まっているため、切なさと歯がゆさを同時に味わうのが肝。実際の病気ではなくファンの自嘲的な言い方。", "vi": "''sub'' + ''병'' (bệnh): trạng thái nghiêng về nam/nữ phụ vốn không có cơ hội với nhân vật chính. Điểm mấu chốt là vai phụ thường dịu dàng, hấp dẫn hơn trong khi kết cục đã định — nên vừa thương vừa ức. Đây là cách fan tự trêu mình, không phải bệnh thật."}}]'::jsonb, '순정만화·드라마 팬덤에서 나온 말. 서브 남주가 메인 남주보다 매력적으로 그려지지만 여주인공과 이어질 가능성이 사실상 없기 때문에, 시청자·독자가 짝사랑하는 인물을 지켜보며 애잔함과 답답함을 동시에 느끼는 현상을 ''병''에 비유했다. 영어권에서는 second lead syndrome으로 번역돼 K-드라마 팬 사이에서 통용된다. 정확한 최초 사용 시점은 확인되지 않는다.', '{"de": "Entstanden im Shoujo-Manga- und K-Drama-Fandom. Weil die zweite Figur attraktiv geschrieben ist, aber praktisch keine Chance hat, empfindet man beim Zusehen Zärtlichkeit und Frust zugleich — daher ''Krankheit''. Englischsprachige Fans sagen second lead syndrome. Eine Erstverwendung ist nicht belegt.", "en": "Born in shoujo-manga and K-drama fandom. Because the second lead is written as appealing yet has virtually no chance with the heroine, viewers watching him pine feel tenderness and frustration at once — hence ''illness''. English-speaking fans call it second lead syndrome. No source pins down its first use.", "es": "Nació en el fandom del manga shoujo y los K-dramas. Como el segundo protagonista se escribe atractivo pero sin opciones reales, ver su amor no correspondido produce ternura y frustración: de ahí lo de ''enfermedad''. En inglés se llama second lead syndrome. No consta su primer uso.", "ja": "少女漫画・ドラマのファンダム発。サブ主人公は魅力的に描かれながらヒロインと結ばれる可能性がほぼないため、その片思いを見守る視聴者が切なさと歯がゆさを同時に感じる現象を「病」に例えた。英語圏ではsecond lead syndromeと訳される。初出は確認できない。", "vi": "Sinh ra từ fandom truyện thiếu nữ và phim Hàn. Vì nam phụ được viết hấp dẫn nhưng gần như không có cửa với nữ chính, người xem vừa thương vừa bức bối — nên gọi là ''bệnh''. Fan nói tiếng Anh gọi là second lead syndrome. Không rõ lần dùng đầu tiên."}'::jsonb, '자기 감정을 웃으며 고백하는 말이라 ''서브병 걸렸다''처럼 스스로에게 붙인다. 남을 두고 ''너 서브병이네''라고 해도 놀리는 정도지 비난은 아니다. 드라마 이야기를 나눌 때 가장 자연스럽고, 실제 연애 상황에 갖다 쓰면 어색하다.', '{"de": "Ein heiteres Geständnis über sich selbst — meist \"Ich habe 서브병\". Über andere gesagt ist es Neckerei, keine Kritik. Passt am besten beim Serien-Talk; auf echte Beziehungen angewandt klingt es schräg.", "en": "It is a cheerful confession about yourself — usually \"I''ve caught 서브병\". Saying it about someone else is teasing, not an insult. It fits drama chat best; applying it to a real relationship sounds off.", "es": "Es una confesión risueña sobre uno mismo: \"me dio 서브병\". Decírselo a otra persona es una broma, no un insulto. Encaja al hablar de series; aplicado a una relación real suena raro.", "ja": "自分の感情を笑って告白する語で「서브병にかかった」と自分に使う。他人に「サブ病だね」と言っても冷やかし程度で非難ではない。ドラマの話題で最も自然で、実際の恋愛に当てはめると不自然。", "vi": "Là lời tự thú vui vẻ về bản thân — thường nói \"tôi mắc 서브병 rồi\". Nói về người khác thì chỉ là trêu, không phải chê. Hợp nhất khi bàn về phim; áp vào chuyện yêu thật thì kỳ."}'::jsonb, array['남주','여주','짝남','과몰입'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Second lead syndrome"}, {"lang": "🇯🇵 JA", "text": "サブ男主病、第二男子病"}, {"lang": "🇨🇳 ZH", "text": "男二病、爱上男二"}, {"lang": "🇻🇳 VI", "text": "Bệnh nam phụ"}, {"lang": "🇪🇸 ES", "text": "Síndrome del segundo protagonista"}, {"lang": "🇩🇪 DE", "text": "Second-Lead-Syndrom"}]'::jsonb),
('475', '사딸라', 'Sa-ttal-la', 'drama', null, '''4달러'' — 안 깎아주면 물러서지 않는 협상 밈', '{"de": "\"Vier Dollar!\" — Meme fürs sture Feilschen", "en": "\"Four dollars!\" — a meme for refusing to budge on a price", "es": "\"¡Cuatro dólares!\" — meme de no ceder en el precio", "ja": "「4ドル」— 値段で一歩も譲らない交渉ミーム", "vi": "\"Bốn đô!\" — meme không nhượng bộ khi mặc cả"}'::jsonb, null, '[{"type": "감탄사", "examples": [{"de": "Was kostet das gebraucht? — Vier Dollar.", "es": "¿Cuánto por esto de segunda mano? — Cuatro dólares.", "ja": "この中古いくら? — サッタラ。", "vi": "Đồ cũ này bao nhiêu? — Bốn đô.", "eng": "How much for this secondhand? — Four dollars. (take it or leave it)", "kor": "이 중고 얼마예요? — 사딸라."}, {"de": "Egal wie oft ich es erkläre, der Teamleiter sagt nur \"Vier Dollar\". Da kommt man nicht durch.", "es": "Por mucho que le explique, el jefe sigue con su \"cuatro dólares\". No hay forma.", "ja": "何度説明してもチーム長はサッタラ。話が通じない。", "vi": "Giải thích mấy lần sếp vẫn \"bốn đô\". Không nói lý được.", "eng": "No matter how many times I explain, the team lead just goes \"four dollars\". There''s no getting through.", "kor": "팀장님 몇 번을 설명해도 사딸라야. 말이 안 통해."}], "definition": "''4달러''를 옛 말투로 발음한 말. 드라마 ''야인시대''(2003)에서 김두한이 미군과 임금 협상을 하며 상대가 무슨 말을 하든 \"사딸라\"만 반복하는 장면에서 나왔다. 지금은 값을 깎거나 조건을 밀어붙일 때, 또는 남의 말을 안 듣고 자기 주장만 되풀이하는 태도를 웃기게 가리킬 때 쓴다.", "definition_i18n": {"de": "Eine altertümliche Aussprache von \"vier Dollar\". Aus der Serie Rustic Period (2003), in der Kim Du-han bei Lohnverhandlungen mit US-Offizieren nur \"Sa-ttal-la\" wiederholt. Heute beim harten Feilschen oder als Spott über jemanden, der stur seine Forderung wiederholt.", "en": "An old-fashioned pronunciation of \"four dollars\". It comes from the 2003 drama Rustic Period, where Kim Du-han negotiates with US officers by simply repeating \"sa-ttal-la\" no matter what they say. Today it is used when haggling hard, or to mock someone who just repeats their demand and ignores everything else.", "es": "Pronunciación anticuada de \"cuatro dólares\". Viene del drama Rustic Period (2003), donde Kim Du-han negocia con oficiales estadounidenses repitiendo solo \"sa-ttal-la\". Hoy se usa al regatear con firmeza o para burlarse de quien repite su exigencia sin escuchar.", "ja": "「4ドル」を古風な発音で言った語。ドラマ『野人時代』(2003)で金斗漢が米軍との賃金交渉で相手が何を言っても「サッタラ」だけを繰り返す場面が由来。今は値切るときや条件を押し通すとき、または人の話を聞かず主張を繰り返す態度を笑うときに使う。", "vi": "Cách phát âm kiểu cũ của \"bốn đô la\". Xuất phát từ phim Rustic Period (2003), khi Kim Du-han đàm phán với lính Mỹ chỉ lặp lại \"sa-ttal-la\". Nay dùng khi mặc cả quyết liệt hoặc trêu người cứ lặp yêu sách mà không nghe ai."}}]'::jsonb, 'SBS 드라마 ''야인시대''(2002~2003) 속 김두한(배우 김영철)의 대사. 방송 당시가 아니라 2018~2019년 ''김두한식 협상''이라는 제목의 짤·영상으로 온라인에서 뒤늦게 재발굴됐고, 2019년 버거킹이 4,900원 세트가 약 4달러인 점에 착안해 김영철을 그대로 기용한 광고를 내면서 전 국민에게 퍼졌다. 이 광고 제품은 누적 1천만 개 판매를 기록했다.', '{"de": "Ein Satz von Kim Du-han (Schauspieler Kim Young-chul) in SBS'' Rustic Period (2002–03). Berühmt wurde er nicht bei der Ausstrahlung, sondern 2018–19 durch Clips der \"Kim-Du-han-Verhandlung\"; 2019 besetzte Burger King Korea denselben Schauspieler für einen Spot zu einem 4.900-Won-Menü (rund vier Dollar) und machte den Spruch landesweit bekannt.", "en": "A line by Kim Du-han (actor Kim Young-chul) in SBS''s Rustic Period (2002–03). It became famous not on air but in 2018–19, when clips titled \"Kim Du-han-style negotiation\" resurfaced online; in 2019 Burger King Korea cast the same actor for an ad pegged to a 4,900-won combo (roughly four dollars), pushing the phrase nationwide. That promotion sold over ten million units.", "es": "Una frase de Kim Du-han (el actor Kim Young-chul) en Rustic Period de SBS (2002-03). Se hizo famosa no al emitirse sino en 2018-19, con clips de \"negociación al estilo Kim Du-han\"; en 2019 Burger King Corea fichó al mismo actor para un anuncio de un combo de 4.900 wones (unos cuatro dólares) y la frase se volvió nacional.", "ja": "SBSドラマ『野人時代』(2002~03)の金斗漢(俳優キム・ヨンチョル)のセリフ。放送当時ではなく2018~19年に「金斗漢式交渉」という切り抜き動画でネットで再発掘され、2019年にバーガーキングが4,900ウォン(約4ドル)のセットに掛けて同俳優を起用した広告で全国に広まった。", "vi": "Câu thoại của Kim Du-han (diễn viên Kim Young-chul) trong phim Rustic Period của SBS (2002–03). Nổi tiếng không phải lúc phát sóng mà vào 2018–19 qua các clip \"đàm phán kiểu Kim Du-han\"; năm 2019 Burger King Hàn mời chính diễn viên đó quảng cáo combo 4.900 won (khoảng bốn đô), đưa câu này ra toàn quốc."}'::jsonb, '짧게 한 마디만 툭 던지는 게 핵심이라 문장으로 늘이면 재미가 사라진다. 실제 흥정에서는 농담 신호로 통하지만, 드라마나 광고를 모르는 상대에게는 그냥 이상한 소리로 들릴 수 있다. 20~40대가 가장 잘 알아듣는다.', '{"de": "Der Witz liegt im knappen Einwort-Einwurf — ausformuliert verpufft er. Beim echten Feilschen ist es ein Augenzwinkern, wer Serie und Werbung nicht kennt, versteht nur Bahnhof. Am besten verstanden von 20- bis 40-Jährigen.", "en": "The joke is the flat, one-word delivery — stretching it into a sentence kills it. In real haggling it reads as a wink, but someone who doesn''t know the drama or the ad will just be confused. People in their 20s to 40s get it best.", "es": "La gracia está en soltarlo seco, en una sola palabra; alargarlo lo arruina. En un regateo real funciona como guiño, pero quien no conozca la serie o el anuncio se quedará perdido. Lo pillan sobre todo los de 20 a 40 años.", "ja": "一言だけぽつりと言うのが肝で、文にすると面白さが消える。実際の値切りでは冗談の合図として通じるが、ドラマや広告を知らない相手にはただの謎の言葉。20~40代に最も通じる。", "vi": "Cái hay là buông đúng một câu cụt — kéo dài ra là mất vui. Khi mặc cả thật thì đây là tín hiệu đùa, nhưng ai không biết phim hay quảng cáo sẽ thấy khó hiểu. Người 20–40 tuổi hiểu rõ nhất."}'::jsonb, array['밈','레전드','가성비'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "\"Four dollars!\" (non-negotiable)"}, {"lang": "🇯🇵 JA", "text": "サッタラ(4ドル、譲らない)"}, {"lang": "🇨🇳 ZH", "text": "四美元(死不让价)"}, {"lang": "🇻🇳 VI", "text": "\"Bốn đô!\" (không nhượng)"}, {"lang": "🇪🇸 ES", "text": "\"¡Cuatro dólares!\""}, {"lang": "🇩🇪 DE", "text": "\"Vier Dollar!\""}]'::jsonb);

